const items=$input.all();
return items.flatMap((item,index)=>{
 const j=item.json;
 const present=v=>v!==undefined&&v!==null&&String(v).trim()!=='';
 const id=v=>/^\d+$/.test(String(v??'').trim())&&Number(v)>0;
 const emailAny=present(j.campaign_id)||present(j.lead_id);
 const emailValid=id(j.campaign_id)&&id(j.lead_id);
 const linkedAny=present(j.campaign_idlinkedin)||present(j.lead_idlinkedin);
 const linkedValid=id(j.campaign_idlinkedin)&&(present(j.lead_idlinkedin)||/^https:\/\/(www\.)?linkedin\.com\//i.test(String(j.linkedin_url||'')));
 if(emailAny&&!emailValid) throw new Error('Incomplete EmailBison identifiers on Airtable record '+j.id+'; no stop requests or status changes performed. Reconcile campaign_id and lead_id.');
 if(linkedAny&&!linkedValid) throw new Error('Incomplete HeyReach identifiers on Airtable record '+j.id+'; no stop requests or status changes performed.');
 if(!emailValid&&!linkedValid) return [];
 return [{json:{...j,hasBisonIdentity:emailValid,hasHeyReachIdentity:linkedValid},pairedItem:{item:index}}];
});
